{
  "lines": [
    {
      "key": "opening",
      "japanese": "あれ、こんにちは。どうしたの、今日？",
      "reading": "アレ、コンニチハ。ドウシタノ、キョウ？",
      "romaji": "Are, konnichiwa. Doushita no, kyou?"
    },
    {
      "key": "reply",
      "japanese": "あ、こんにちは。ちょっと買い物。",
      "reading": "ア、コンニチハ。チョットカイモノ。",
      "romaji": "A, konnichiwa. Chotto kaimono."
    },
    {
      "key": "suggestion",
      "japanese": "そっか。じゃあ、ご飯でもどう？",
      "reading": "ソッカ。ジャア、ゴハンデモドウ？",
      "romaji": "Sokka. Jaa, gohan demo dou?"
    },
    {
      "key": "acceptance",
      "japanese": "いいね！行こう行こう。",
      "reading": "イイネ！イコウイコウ。",
      "romaji": "Ii ne! Ikou ikou."
    }
  ]
}

